input.content:
:root {
  --blood: #c1121f;
  --blood-dark: #6a040f;
  --blood-bright: #ff2a2a;
  --bone: #e8dcc3;
  --sand: #cbb281;
  --ink: #0a0505;
  --steel: #9aa3ad;
  --gold: #d9a441;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden; background: #0a0505; color: var(--bone);
  font-family: 'Trebuchet MS', 'Segoe UI', sans-serif;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
}

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute; inset: 0; width: 100%; height: 100%;
  display: block; outline: none; touch-action: none;
}

.hidden { display: none !important; }

/* ================= ATMOSPHERE ================= */
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 5;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 40%, rgba(0,0,0,.48) 78%, rgba(0,0,0,.9) 100%),
    linear-gradient(to bottom, rgba(30,0,0,.18), transparent 35%, transparent 75%, rgba(0,0,0,.35));
}

#blood-overlay {
  position: absolute; inset: -5%; pointer-events: none; z-index: 8;
  opacity: 0; transition: opacity .6s ease;
  background:
    radial-gradient(circle at 12% 18%, rgba(120,0,4,.85) 0 2.2%, rgba(100,0,3,.5) 2.4% 4%, transparent 6%),
    radial-gradient(circle at 86% 74%, rgba(130,0,5,.8) 0 3%, rgba(95,0,3,.4) 3.2% 5.4%, transparent 7%),
    radial-gradient(circle at 72% 9%, rgba(110,0,4,.7) 0 1.6%, transparent 4%),
    radial-gradient(circle at 24% 88%, rgba(110,0,4,.7) 0 2.4%, transparent 5%),
    radial-gradient(ellipse at 50% 118%, rgba(90,0,2,.55) 0 30%, transparent 55%);
  filter: blur(.4px) saturate(1.2);
}

#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 9; opacity: 0;
  background: radial-gradient(ellipse at center, rgba(150,0,0,0) 32%, rgba(180,0,0,.62) 80%, rgba(255,10,10,.8) 100%);
  transition: opacity .18s ease-out;
}

#lowhp {
  position: absolute; inset: 0; pointer-events: none; z-index: 7; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(110,0,0,.55) 100%);
}
#lowhp.active { animation: lowhp 1.1s ease-in-out infinite; }
@keyframes lowhp { 0%,100% { opacity: .18; } 50% { opacity: .72; } }

/* ================= HUD ================= */
#hud {
  position: absolute; inset: 0; z-index: 12; pointer-events: none;
  padding: calc(16px + var(--safe-t)) calc(20px + var(--safe-r)) calc(16px + var(--safe-b)) calc(20px + var(--safe-l));
  font-family: 'Trebuchet MS', sans-serif;
}

.hud-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }

.hud-left { width: min(340px, 34vw); }
.health-label {
  display: flex; justify-content: space-between; align-items: baseline;
  font-size: 10px; letter-spacing: .28em; color: #c9b28d; text-shadow: 0 1px 3px #000;
  margin-bottom: 5px;
}
.health-label span:last-child { font-size: 14px; letter-spacing: .06em; color: var(--bone); font-weight: 700; }

.health-bar {
  position: relative; height: 21px; width: 100%;
  background: linear-gradient(#241010, #150808);
  border: 1px solid rgba(232,220,195,.32);
  box-shadow: 0 0 0 2px rgba(0,0,0,.45), inset 0 0 12px #000;
  clip-path: polygon(0 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  overflow: hidden;
}
#health-fill {
  position: absolute; top: 0; left: 0; height: 100%; width: 100%;
  background: linear-gradient(180deg, #e33b3b, #a30c19 55%, #5c030c);
  box-shadow: inset 0 2px 0 rgba(255,180,180,.35), 0 0 12px rgba(200,0,0,.55);
  transition: width .18s ease-out;
}
#health-ghost {
  position: absolute; top: 0; left: 0; height: 100%; width: 100%;
  background: rgba(255,235,220,.4); transition: width .6s ease .15s;
  mix-blend-mode: screen;
}
.health-ticks {
  position: absolute; inset: 0; pointer-events: none;
  background-image: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(0,0,0,.35) calc(10% - 1px) 10%);
}

#dash-wrap {
  position: relative; margin-top: 8px; height: 5px; width: 62%;
  background: rgba(0,0,0,.6); border: 1px solid rgba(232,220,195,.16);
  overflow: visible;
}
#dash-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #6f7b86, #c8d2da); }
#dash-wrap span {
  position: absolute; left: calc(100% + 8px); top: -5px; font-size: 8px; letter-spacing: .25em; color: #8f8069;
}
#dash-wrap.cooling #dash-fill { background: linear-gradient(90deg, #4a1a1a, #7a2a2a); }

.hud-center { text-align: center; flex: 1; padding-top: 2px; }
#wave-label {
  font-family: Impact, 'Arial Black', sans-serif; font-size: clamp(20px, 2.4vw, 30px);
  letter-spacing: .14em; color: var(--bone); text-shadow: 0 2px 0 #000, 0 0 24px rgba(193,18,31,.6);
}
#enemy-label { font-size: 9px; letter-spacing: .3em; color: #b28f6f; margin-top: 2px; text-shadow: 0 1px 2px #000; }

.hud-right { display: flex; gap: 22px; text-align: right; }
.stat b { display: block; font-family: Impact, 'Arial Black', sans-serif; font-size: 22px; letter-spacing: .05em; line-height: 1; color: var(--bone); text-shadow: 0 1px 3px #000; }
.stat small { font-size: 8px; letter-spacing: .24em; color: #a58c70; }
.stat.combo b { color: var(--blood-bright); text-shadow: 0 0 12px rgba(255,30,30,.8); }

#weapon-hud {
  position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  display: flex; align-items: center; gap: 10px; opacity: .9;
}
#weapon-icon { width: 34px; height: 34px; color: var(--steel); filter: drop-shadow(0 2px 3px #000); }
#weapon-icon svg { width: 100%; height: 100%; }
#weapon-name { font-family: Impact, 'Arial Black', sans-serif; letter-spacing: .12em; font-size: 13px; color: #cfc3ac; }
#weapon-sub { font-size: 8px; letter-spacing: .22em; color: #8e785e; margin-top: 2px; }

#boss-bar {
  position: absolute; left: 50%; top: calc(78px + var(--safe-t)); transform: translateX(-50%);
  width: min(520px, 60vw); text-align: center;
}
.boss-name { font-family: Impact, sans-serif; font-size: 13px; letter-spacing: .24em; color: #e6b06b; text-shadow: 0 1px 4px #000; margin-bottom: 4px; }
.boss-track { height: 12px; background: #190808; border: 1px solid #6b4a24; box-shadow: 0 0 0 2px #000; }
#boss-fill { height: 100%; width: 100%; background: linear-gradient(#f0a33c, #8a3f0d); transition: width .2s; }

/* crosshair */
#crosshair {
  position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; margin: -13px 0 0 -13px;
  border: 1px solid rgba(232,220,195,.45); border-radius: 50%;
  transition: border-color .12s, transform .12s;
  box-shadow: 0 0 0 1px rgba(0,0,0,.35);
}
#crosshair::before, #crosshair::after {
  content: ''; position: absolute; background: rgba(232,220,195,.55);
}
#crosshair::before { left: 50%; top: -7px; width: 1px; height: 4px; }
#crosshair::after { left: 50%; bottom: -7px; width: 1px; height: 4px; }
#crosshair i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; margin: -1.5px; border-radius: 50%; background: rgba(255,240,225,.9); }
#crosshair.hot { border-color: var(--blood-bright); transform: scale(1.16); box-shadow: 0 0 12px rgba(255,30,30,.65); }
#crosshair.hot::before, #crosshair.hot::after { background: var(--blood-bright); }

/* announcements */
#announce {
  position: absolute; left: 50%; top: 30%; transform: translate(-50%, -50%) scale(.9);
  text-align: center; opacity: 0; transition: opacity .25s, transform .35s cubic-bezier(.2,1.4,.4,1);
  width: 92vw; pointer-events: none;
}
#announce.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
#announce .big {
  font-family: Impact, 'Arial Black', sans-serif; font-size: clamp(44px, 8.5vw, 110px);
  line-height: .92; letter-spacing: .03em; color: var(--bone);
  text-shadow: 0 4px 0 #2a0000, 0 0 40px rgba(193,18,31,.65), 0 8px 30px #000;
  -webkit-text-stroke: 1px rgba(0,0,0,.5);
}
#announce .small { margin-top: 10px; font-size: clamp(9px, 1.1vw, 12px); letter-spacing: .42em; color: #c79d72; text-shadow: 0 1px 3px #000; }
#announce .bloodline { display: block; width: 120px; height: 2px; margin: 14px auto 0; background: linear-gradient(90deg, transparent, var(--blood), transparent); }

/* floating combat text */
#popups { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.popup {
  position: absolute; transform: translate(-50%, -50%);
  font-family: Impact, 'Arial Black', sans-serif; letter-spacing: .08em;
  font-size: 17px; color: #ffdfb0; text-shadow: 0 2px 0 #300, 0 0 12px rgba(255,60,40,.9);
  will-change: transform, opacity; white-space: nowrap;
}
.popup.gore { color: #ff453a; font-size: 22px; text-shadow: 0 2px 0 #2a0000, 0 0 18px #c1121f; }
.popup.big { font-size: 30px; }
.popup.gold { color: var(--gold); }

#hint {
  position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(22px + var(--safe-b));
  font-size: 8px; letter-spacing: .2em; color: rgba(214,196,168,.4);
}
#pause-btn {
  position: absolute; right: calc(18px + var(--safe-r)); top: calc(74px + var(--safe-t));
  width: 34px; height: 34px; border: 1px solid rgba(232,220,195,.22); background: rgba(10,4,4,.45);
  color: #c9b28d; font-size: 11px; letter-spacing: .05em; cursor: pointer; pointer-events: auto;
  border-radius: 2px; backdrop-filter: blur(3px);
}
#pause-btn:hover { background: rgba(90,10,10,.6); color: #fff; }

/* ================= SCREENS ================= */
.screen { position: absolute; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center; }
.menu-shade {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(20,3,3,.35) 0%, rgba(8,2,2,.78) 60%, rgba(3,1,1,.94) 100%),
    linear-gradient(to bottom, rgba(0,0,0,.55), transparent 30%, transparent 65%, rgba(0,0,0,.75));
}
.menu-inner {
  position: relative; z-index: 2; width: min(880px, 92vw); text-align: center;
  padding: 20px; max-height: 100dvh; overflow-y: auto; scrollbar-width: none;
}
.menu-inner::-webkit-scrollbar { display: none; }

.eyebrow { font-size: 10px; letter-spacing: .5em; color: #c27a5a; text-shadow: 0 1px 4px #000; }
h1 {
  margin: 8px 0 0; font-family: Impact, 'Arial Black', sans-serif;
  font-size: clamp(66px, 15vw, 172px); line-height: .82; letter-spacing: .01em;
  color: #efe4cd;
  text-shadow: 0 6px 0 #3a0404, 0 0 70px rgba(193,18,31,.5), 0 18px 40px #000;
  -webkit-text-stroke: 2px rgba(30,0,0,.45);
}
h1 span { color: var(--blood); text-shadow: 0 6px 0 #2a0000, 0 0 70px rgba(255,20,20,.6), 0 16px 40px #000; }
.ribbon {
  display: inline-block; margin-top: 10px; padding: 5px 18px;
  border-top: 1px solid rgba(193,18,31,.6); border-bottom: 1px solid rgba(193,18,31,.6);
  font-size: 9px; letter-spacing: .5em; color: #c9a474;
}
.tagline { margin: 16px 0 22px; font-size: clamp(13px, 1.5vw, 16px); line-height: 1.55; color: #cbb99d; }
.tagline em { color: #e8a09a; font-style: normal; }

.weapon-pick { display: flex; gap: 16px; justify-content: center; margin: 0 auto 22px; max-width: 660px; }
.weapon-card {
  position: relative; flex: 1; max-width: 310px; min-height: 174px;
  padding: 14px 14px 12px; cursor: pointer; text-align: left;
  color: #bfae94; background: linear-gradient(160deg, rgba(38,12,12,.78), rgba(9,4,4,.88));
  border: 1px solid rgba(232,220,195,.16);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  transition: transform .18s ease, border-color .18s, background .18s;
  font-family: inherit;
}
.weapon-card:hover { transform: translateY(-3px); border-color: rgba(232,220,195,.4); }
.weapon-card.selected {
  border-color: rgba(220,38,38,.85);
  background: linear-gradient(160deg, rgba(72,10,12,.85), rgba(14,4,4,.92));
  box-shadow: inset 0 0 34px rgba(193,18,31,.18), 0 0 30px rgba(193,18,31,.12);
}
.weapon-card.selected .card-check { opacity: 1; }
.card-art { height: 58px; color: #b9a58c; margin-bottom: 4px; }
.weapon-card.selected .card-art { color: #e2c9a2; filter: drop-shadow(0 0 10px rgba(255,60,40,.35)); }
.card-art svg { height: 100%; width: auto; }
.card-name { font-family: Impact, 'Arial Black', sans-serif; font-size: 24px; letter-spacing: .14em; color: #e9dcc3; }
.card-desc { font-size: 11px; line-height: 1.45; color: #b29579; margin-top: 3px; }
.card-tag { margin-top: 8px; font-size: 8px; letter-spacing: .26em; color: #8c6a4e; }
.card-check {
  position: absolute; right: 12px; top: 10px; opacity: 0; color: var(--blood-bright);
  font-size: 14px; transition: opacity .2s;
}

.big-btn {
  position: relative; padding: 16px 44px; cursor: pointer;
  background: linear-gradient(180deg, #a70f1c, #6a0410);
  border: 1px solid rgba(255,190,170,.35); color: #fff0e6;
  font-family: Impact, 'Arial Black', sans-serif; font-size: 20px; letter-spacing: .2em;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  box-shadow: 0 8px 30px rgba(120,0,0,.35), inset 0 1px 0 rgba(255,255,255,.18);
  transition: transform .15s, filter .15s;
}
.big-btn:hover { transform: translateY(-2px); filter: brightness(1.15); }
.big-btn:active { transform: translateY(1px); }
.big-btn span { position: relative; z-index: 2; }

.ghost-btn {
  display: block; margin: 12px auto 0; padding: 9px 22px; cursor: pointer;
  background: transparent; border: 1px solid rgba(232,220,195,.22); color: #a78e74;
  font-family: inherit; font-size: 10px; letter-spacing: .24em;
}
.ghost-btn:hover { color: #e8dcc3; border-color: rgba(232,220,195,.5); }

.controls-hint { margin-top: 18px; font-size: 9px; letter-spacing: .22em; color: #8a725a; }
.gore-note { margin-top: 14px; font-size: 9px; letter-spacing: .32em; color: #8e1515; text-shadow: 0 0 16px rgba(193,18,31,.55); }
.menu-footer {
  position: absolute; bottom: 14px; left: 0; right: 0; text-align: center;
  font-size: 8px; letter-spacing: .38em; color: rgba(190,160,130,.28); z-index: 2;
}

/* pause / death */
#pause .pause-inner, #death .death-inner { position: relative; z-index: 2; text-align: center; width: min(560px, 92vw); }
#pause h2, #death h2 {
  font-family: Impact, 'Arial Black', sans-serif; font-size: clamp(40px, 7vw, 76px);
  letter-spacing: .06em; margin: 10px 0 2px; color: #e9dcc3; text-shadow: 0 4px 0 #2a0000, 0 0 50px rgba(193,18,31,.5);
}
#pause p { color: #9d8266; font-size: 12px; letter-spacing: .14em; margin-bottom: 24px; }

#death { background: rgba(4,0,0,.35); }
.death-shade {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 45%, rgba(90,0,3,.6), rgba(4,0,0,.94) 72%);
  animation: deathfade 1.4s ease both;
}
@keyframes deathfade { from { opacity: 0; } to { opacity: 1; } }
.death-inner .eyebrow { color: #a8473d; }
#death h2 { color: #b3131f; -webkit-text-stroke: 1px #310000; text-shadow: 0 5px 0 #1a0000, 0 0 70px rgba(255,20,20,.32); }
.death-stats { display: flex; justify-content: center; gap: clamp(26px, 8vw, 70px); margin: 26px 0 18px; }
.death-stats b { display: block; font-family: Impact, sans-serif; font-size: 38px; line-height: 1; color: #e5d6bd; }
.death-stats small { font-size: 8px; letter-spacing: .3em; color: #9b7d61; }
#death-line { font-size: 12px; letter-spacing: .08em; color: #b39376; font-style: italic; margin-bottom: 24px; }

/* ================= TOUCH ================= */
#touch-controls { position: absolute; inset: 0; z-index: 14; pointer-events: none; }
#joystick {
  position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(26px + var(--safe-b));
  width: 132px; height: 132px; border-radius: 50%;
  border: 1px solid rgba(232,220,195,.22);
  background: radial-gradient(circle, rgba(30,10,10,.3), rgba(0,0,0,.4));
  pointer-events: auto; touch-action: none;
}
#joystick::after {
  content: ''; position: absolute; inset: 28%; border-radius: 50%; border: 1px solid rgba(232,220,195,.1);
}
#stick {
  position: absolute; left: 50%; top: 50%; width: 58px; height: 58px; margin: -29px;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, #c9b28d, #6d553c);
  box-shadow: 0 4px 12px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.35);
  transition: transform .06s linear;
}
.touch-right {
  position: absolute; right: calc(20px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: flex; align-items: flex-end; gap: 14px; pointer-events: none;
}
#attack-btn, #dash-btn {
  pointer-events: auto; touch-action: none; border-radius: 50%;
  font-family: Impact, 'Arial Black', sans-serif; color: #f2e2c9;
  border: 1px solid rgba(255,170,150,.35);
  background: radial-gradient(circle at 40% 30%, rgba(160,20,26,.9), rgba(80,4,10,.9));
  box-shadow: 0 6px 18px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.2);
}
#attack-btn { width: 94px; height: 94px; font-size: 15px; letter-spacing: .06em; }
#dash-btn { width: 62px; height: 62px; font-size: 10px; letter-spacing: .06em; background: radial-gradient(circle at 40% 30%, rgba(70,62,54,.92), rgba(24,20,18,.92)); margin-bottom: 8px; }
#attack-btn:active, #dash-btn:active { filter: brightness(1.35); transform: scale(.95); }

#rotate-hint {
  position: absolute; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center;
  background: #0a0505; color: #c9b28d; font-size: 12px; letter-spacing: .2em; text-align: center; padding: 30px;
}

.touch-only { display: none; }
body.touch .touch-only { display: block; }
body.touch .desktop-only { display: none; }
body.touch #hint, body.touch #pause-btn { display: none; }
body.touch .hud-left { width: min(240px, 40vw); }
body.touch #weapon-hud { bottom: calc(170px + var(--safe-b)); }

/* ================= RESPONSIVE ================= */
@media (max-width: 720px) {
  .hud-top { gap: 8px; }
  .health-bar { height: 16px; }
  .health-label { font-size: 8px; }
  .health-label span:last-child { font-size: 11px; }
  .hud-center { position: absolute; left: 50%; top: 74px; transform: translateX(-50%); width: 100%; }
  #wave-label { font-size: 18px; }
  #enemy-label { font-size: 7px; }
  .hud-right { gap: 14px; }
  .stat b { font-size: 17px; }
  .stat small { font-size: 7px; }
  .stat.combo { position: absolute; right: 18px; top: 108px; }
  #boss-bar { width: 74vw; top: 120px; }
  .weapon-pick { flex-direction: column; align-items: stretch; max-width: 420px; }
  .weapon-card { min-height: 0; display: grid; grid-template-columns: 56px 1fr; grid-template-rows: auto auto auto; gap: 0 10px; padding: 10px 12px; }
  .card-art { grid-row: 1 / 4; height: 48px; align-self: center; }
  .card-name { font-size: 19px; }
  .card-desc { font-size: 10px; }
  .card-tag { display: none; }
  .menu-inner { padding-top: calc(14px + var(--safe-t)); padding-bottom: calc(26px + var(--safe-b)); }
  h1 { font-size: clamp(58px, 19vw, 110px); }
  .tagline { margin: 12px 0 16px; }
  .ribbon { font-size: 7px; }
  .gore-note { margin-top: 10px; }
  .menu-footer { display: none; }
  #popups .popup { font-size: 14px; }
  #weapon-hud { bottom: calc(20px + var(--safe-b)); left: calc(18px + var(--safe-l)); }
}

@media (max-height: 540px) and (orientation: landscape) {
  .menu-inner { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: auto auto auto 1fr; align-items: center; column-gap: 20px; width: min(900px, 94vw); }
  .eyebrow { grid-column: 1 / 3; }
  h1 { grid-column: 1 / 3; font-size: clamp(44px, 12vh, 84px); margin: 0; }
  .ribbon { display: none; }
  .tagline { grid-column: 1 / 3; margin: 8px 0 12px; font-size: 11px; }
  .weapon-pick { grid-column: 1 / 3; margin-bottom: 12px; flex-direction: row; }
  .weapon-card { min-height: 0; padding: 8px 12px; display: grid; grid-template-columns: 44px 1fr; gap: 0 8px; }
  .card-art { grid-row: 1 / 4; height: 40px; align-self: center; }
  .card-name { font-size: 17px; }
  .card-desc { font-size: 9px; }
  .card-tag { display: none; }
  .big-btn { padding: 11px 32px; font-size: 16px; grid-column: 1 / 3; justify-self: center; }
  .controls-hint, .gore-note { display: none; }
}

import * as THREE from '../vendor/three.module.js';

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const easeOut = (t) => 1 - Math.pow(1 - t, 3);
export const easeIn = (t) => t * t * t;

export function canvasTexture(w, h, draw, opts = {}) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  if (opts.repeat) {
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(opts.repeat[0], opts.repeat[1]);
  }
  tex.anisotropy = opts.aniso ?? 4;
  return tex;
}

export function makeSandTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#a98c5d';
    ctx.fillRect(0, 0, w, h);
    // broad tonal patches
    for (let i = 0; i < 60; i++) {
      const x = Math.random() * w, y = Math.random() * h, r = rand(20, 100);
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      const shade = Math.random() > 0.5 ? 'rgba(80,58,36,.10)' : 'rgba(220,195,150,.10)';
      g.addColorStop(0, shade); g.addColorStop(1, 'transparent');
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
    }
    // grain
    for (let i = 0; i < 14000; i++) {
      const x = Math.random() * w, y = Math.random() * h;
      const v = Math.random();
      ctx.fillStyle = v > 0.7 ? 'rgba(60,42,26,.35)' : v > 0.35 ? 'rgba(200,176,130,.28)' : 'rgba(0,0,0,.12)';
      ctx.fillRect(x, y, rand(0.6, 1.8), rand(0.6, 1.8));
    }
    // raked lines
    ctx.strokeStyle = 'rgba(70,50,30,.10)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 70; i++) {
      const y = Math.random() * h;
      ctx.beginPath(); ctx.moveTo(0, y);
      ctx.bezierCurveTo(w * 0.3, y + rand(-8, 8), w * 0.7, y + rand(-8, 8), w, y + rand(-4, 4));
      ctx.stroke();
    }
  }, { repeat: [5, 5], aniso: 8 });
}

export function makeStoneTexture() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = '#4a403b';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 1800; i++) {
      const v = Math.random();
      ctx.fillStyle = v > 0.5 ? `rgba(${90 + Math.random() * 40},${80 + Math.random() * 30},${70 + Math.random() * 30},.4)` : 'rgba(20,16,14,.35)';
      const s = rand(1, 6);
      ctx.fillRect(Math.random() * w, Math.random() * h, s, s * rand(0.4, 1.6));
    }
    // cracks
    ctx.strokeStyle = 'rgba(14,10,9,.5)';
    for (let i = 0; i < 8; i++) {
      let x = Math.random() * w, y = Math.random() * h;
      ctx.beginPath(); ctx.moveTo(x, y);
      for (let k = 0; k < 5; k++) { x += rand(-22, 22); y += rand(6, 30); ctx.lineTo(x, y); }
      ctx.stroke();
    }
  }, { repeat: [2, 1] });
}

export function makeRadialTexture(inner = 'rgba(255,80,40,1)', outer = 'rgba(255,80,40,0)') {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.35, inner);
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export function makeBloodBlobTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    // central blot
    for (let i = 0; i < 26; i++) {
      const x = w / 2 + rand(-22, 22), y = h / 2 + rand(-22, 22);
      const r = rand(6, 26);
      const g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, 'rgba(95,2,6,.9)');
      g.addColorStop(0.7, 'rgba(75,1,4,.55)');
      g.addColorStop(1, 'rgba(60,0,2,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
    }
    // splatter droplets
    for (let i = 0; i < 24; i++) {
      const a = Math.random() * Math.PI * 2, d = rand(30, 60);
      const x = w / 2 + Math.cos(a) * d, y = h / 2 + Math.sin(a) * d;
      ctx.fillStyle = `rgba(${randInt(70, 115)},0,${randInt(2, 10)},${rand(0.4, 0.85)})`;
      ctx.beginPath(); ctx.arc(x, y, rand(1.5, 5), 0, 7); ctx.fill();
    }
  });
}

export function makeBannerTexture() {
  return canvasTexture(128, 192, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#6d0911'); g.addColorStop(0.6, '#4a050b'); g.addColorStop(1, '#2c0206');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    // torn bottom
    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.beginPath(); ctx.moveTo(0, h); ctx.lineTo(0, h - 18);
    for (let x = 0; x <= w; x += 16) ctx.lineTo(x + rand(-6, 6), h - 18 + rand(-14, 14));
    ctx.lineTo(w, h); ctx.closePath(); ctx.fill();
    // border
    ctx.strokeStyle = 'rgba(220,170,90,.35)'; ctx.lineWidth = 2;
    ctx.strokeRect(6, 6, w - 12, h - 26);
    // emblem
    ctx.fillStyle = 'rgba(16,3,3,.75)';
    ctx.beginPath(); ctx.arc(w / 2, 76, 28, 0, 7); ctx.fill();
    ctx.strokeStyle = 'rgba(220,170,90,.5)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(w / 2, 76, 28, 0, 7); ctx.stroke();
    // skull-ish mark
    ctx.fillStyle = 'rgba(205,185,150,.55)';
    ctx.beginPath(); ctx.arc(w / 2, 70, 10, 0, 7); ctx.fill();
    ctx.fillRect(w / 2 - 7, 76, 14, 9);
    ctx.fillStyle = 'rgba(30,4,4,.9)';
    ctx.beginPath(); ctx.arc(w / 2 - 4, 69, 2.6, 0, 7); ctx.fill();
    ctx.beginPath(); ctx.arc(w / 2 + 4, 69, 2.6, 0, 7); ctx.fill();
    // grime
    for (let i = 0; i < 40; i++) {
      ctx.fillStyle = `rgba(10,0,0,${rand(0.05, 0.2)})`;
      ctx.fillRect(rand(0, w), rand(0, h), rand(2, 18), rand(1, 8));
    }
  });
}

import * as THREE from '../vendor/three.module.js';
import {
  rand, randInt, makeSandTexture, makeStoneTexture, makeRadialTexture,
  makeBannerTexture
} from './utils.js';

export function createArena(scene, renderer, isMobile = false) {
  const group = new THREE.Group();
  scene.add(group);

  scene.background = new THREE.Color(0x140606);
  scene.fog = new THREE.FogExp2(0x1a0707, 0.016);

  /* ---------------- lights ---------------- */
  const hemi = new THREE.HemisphereLight(0x7a4038, 0x170b07, 1.0);
  scene.add(hemi);

  const key = new THREE.DirectionalLight(0xffb37a, 2.1);
  key.position.set(9, 17, 7);
  key.castShadow = !isMobile;
  key.shadow.mapSize.set(1024, 1024);
  key.shadow.camera.left = -22;
  key.shadow.camera.right = 22;
  key.shadow.camera.top = 22;
  key.shadow.camera.bottom = -22;
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 55;
  key.shadow.bias = -0.0012;
  scene.add(key);

  const rim = new THREE.DirectionalLight(0x5f7fa8, 0.8);
  rim.position.set(-10, 8, -12);
  scene.add(rim);

  const torchLights = [];
  for (let i = 0; i < 4; i++) {
    const pl = new THREE.PointLight(0xff6a20, 26, 17, 2);
    torchLights.push(pl);
    scene.add(pl);
  }

  /* ---------------- sky & moon ---------------- */
  const starGeo = new THREE.BufferGeometry();
  const starPos = [];
  for (let i = 0; i < 260; i++) {
    const a = Math.random() * Math.PI * 2;
    const y = rand(8, 70);
    const r = Math.sqrt(Math.max(0, 1 - (y / 80) ** 2)) * 120;
    starPos.push(Math.cos(a) * r, y, Math.sin(a) * r);
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
    color: 0xd9b9a0, size: 0.55, sizeAttenuation: true, transparent: true, opacity: 0.55, fog: false, depthWrite: false
  }));
  scene.add(stars);

  const moonTex = makeRadialTexture('rgba(255,120,80,.95)', 'rgba(180,20,10,0)');
  const moon = new THREE.Sprite(new THREE.SpriteMaterial({
    map: moonTex, color: 0xff9a6a, transparent: true, opacity: 0.9,
    blending: THREE.AdditiveBlending, depthWrite: false, fog: false
  }));
  moon.scale.set(34, 34, 1);
  moon.position.set(38, 34, -86);
  scene.add(moon);
  const moonCore = new THREE.Sprite(new THREE.SpriteMaterial({
    map: moonTex, color: 0xfff0d0, transparent: true, opacity: 0.95,
    blending: THREE.AdditiveBlending, depthWrite: false, fog: false
  }));
  moonCore.scale.set(12, 12, 1);
  moonCore.position.copy(moon.position);
  scene.add(moonCore);

  /* ---------------- sand ---------------- */
  const sandTex = makeSandTexture();
  const sandMat = new THREE.MeshStandardMaterial({
    map: sandTex, color: 0xd8c39a, roughness: 1, metalness: 0
  });
  const sand = new THREE.Mesh(new THREE.CircleGeometry(19.4, 96), sandMat);
  sand.rotation.x = -Math.PI / 2;
  sand.receiveShadow = true;
  group.add(sand);

  // dark earth beyond the arena
  const outside = new THREE.Mesh(
    new THREE.CircleGeometry(90, 48),
    new THREE.MeshStandardMaterial({ color: 0x211310, roughness: 1 })
  );
  outside.rotation.x = -Math.PI / 2;
  outside.position.y = -0.03;
  group.add(outside);

  // central summoning stain
  const stainTex = makeRadialTexture('rgba(60,2,2,.65)', 'rgba(40,0,0,0)');
  const stain = new THREE.Mesh(
    new THREE.CircleGeometry(5.5, 48),
    new THREE.MeshBasicMaterial({ map: stainTex, transparent: true, opacity: 0.8, depthWrite: false })
  );
  stain.rotation.x = -Math.PI / 2;
  stain.position.y = 0.012;
  group.add(stain);

  // ring etched into the sand
  const runeRing = new THREE.Mesh(
    new THREE.RingGeometry(7.4, 7.55, 64),
    new THREE.MeshBasicMaterial({ color: 0x3b0a08, transparent: true, opacity: 0.7, depthWrite: false })
  );
  runeRing.rotation.x = -Math.PI / 2;
  runeRing.position.y = 0.014;
  group.add(runeRing);

  /* ---------------- arena wall ---------------- */
  const stoneTex = makeStoneTexture();
  const stoneMat = new THREE.MeshStandardMaterial({ map: stoneTex, color: 0x6b5c54, roughness: 0.95 });
  const stoneDark = new THREE.MeshStandardMaterial({ map: stoneTex, color: 0x40332e, roughness: 1 });

  const segs = 46;
  const blockGeo = new THREE.BoxGeometry(2.55, 1, 1.0);
  const blocks = new THREE.InstancedMesh(blockGeo, stoneMat, segs);
  blocks.castShadow = !isMobile;
  blocks.receiveShadow = true;
  const dummy = new THREE.Object3D();
  const wallR = 19.3;
  for (let i = 0; i < segs; i++) {
    const a = (i / segs) * Math.PI * 2;
    const h = rand(1.9, 2.35);
    dummy.position.set(Math.sin(a) * wallR, h / 2, Math.cos(a) * wallR);
    dummy.rotation.set(0, a, 0);
    dummy.scale.set(1, h, 1);
    dummy.updateMatrix();
    blocks.setMatrixAt(i, dummy.matrix);
  }
  group.add(blocks);

  const cap = new THREE.Mesh(
    new THREE.TorusGeometry(wallR, 0.42, 8, 72),
    stoneMat
  );
  cap.rotation.x = -Math.PI / 2;
  cap.position.y = 2.3;
  cap.castShadow = !isMobile;
  group.add(cap);

  // columns
  const colGeo = new THREE.BoxGeometry(0.95, 4.6, 0.95);
  const capGeo = new THREE.BoxGeometry(1.5, 0.4, 1.5);
  const columnPoints = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2 + Math.PI / 8;
    const x = Math.sin(a) * 19.35, z = Math.cos(a) * 19.35;
    const col = new THREE.Mesh(colGeo, stoneDark);
    col.position.set(x, 2.5, z);
    col.rotation.y = a;
    col.castShadow = !isMobile;
    group.add(col);
    const c = new THREE.Mesh(capGeo, stoneMat);
    c.position.set(x, 4.85, z);
    c.rotation.y = a;
    group.add(c);
    columnPoints.push(new THREE.Vector3(x, 5.15, z));
  }

  /* ---------------- stands & crowd ---------------- */
  const standMat = new THREE.MeshStandardMaterial({ map: stoneTex, color: 0x5a4b43, roughness: 1 });
  const seatMat = new THREE.MeshStandardMaterial({ color: 0x332a26, roughness: 1 });
  for (let tier = 0; tier < 3; tier++) {
    const rIn = 20.6 + tier * 1.65;
    const ring = new THREE.Mesh(new THREE.RingGeometry(rIn, rIn + 1.65, 64), seatMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 2.3 + tier * 1.0;
    ring.receiveShadow = true;
    group.add(ring);
    const lip = new THREE.Mesh(
      new THREE.CylinderGeometry(rIn + 1.65, rIn + 1.65, 0.7, 64, 1, true),
      standMat
    );
    lip.position.y = 2.3 + tier * 1.0 - 0.35;
    group.add(lip);
  }

  const crowdCount = isMobile ? 150 : 270;
  const crowdMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true });
  const crowdBodies = new THREE.InstancedMesh(new THREE.CapsuleGeometry(0.17, 0.34, 2, 6), crowdMat, crowdCount);
  const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  const crowdHeads = new THREE.InstancedMesh(new THREE.SphereGeometry(0.125, 6, 5), headMat, crowdCount);
  crowdBodies.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  crowdHeads.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  const crowd = [];
  const clothColors = [0x2b1c1a, 0x3a2a20, 0x241e26, 0x3d2b1d, 0x1f1a22, 0x4a2b22, 0x2f3336, 0x553326];
  const skinColors = [0xc98f6b, 0xa87050, 0x8a5a3f, 0xd7a47c, 0x6b4634, 0xbb8060];
  for (let i = 0; i < crowdCount; i++) {
    const tier = i % 3;
    const a = Math.random() * Math.PI * 2;
    const r = 20.9 + tier * 1.65 + rand(0.2, 1.3);
    const baseY = 3.05 + tier * 1.0 + rand(0, 0.12);
    const x = Math.sin(a) * r, z = Math.cos(a) * r;
    crowd.push({ a, r, x, z, y: baseY, phase: Math.random() * 7, speed: rand(1.1, 2.3), amp: rand(0.02, 0.09), tier });
    crowdBodies.setColorAt(i, new THREE.Color(clothColors[randInt(0, clothColors.length - 1)]));
    crowdHeads.setColorAt(i, new THREE.Color(skinColors[randInt(0, skinColors.length - 1)]));
    dummy.position.set(x, baseY, z);
    dummy.rotation.set(0, a, 0);
    dummy.scale.setScalar(rand(0.92, 1.15));
    dummy.updateMatrix();
    crowdBodies.setMatrixAt(i, dummy.matrix);
    dummy.position.y = baseY + 0.44;
    dummy.updateMatrix();
    crowdHeads.setMatrixAt(i, dummy.matrix);
  }
  crowdBodies.instanceColor.needsUpdate = true;
  crowdHeads.instanceColor.needsUpdate = true;
  group.add(crowdBodies, crowdHeads);

  /* ---------------- banners ---------------- */
  const bannerTex = makeBannerTexture();
  const bannerMat = new THREE.MeshStandardMaterial({
    map: bannerTex, color: 0xffffff, roughness: 0.95, side: THREE.DoubleSide
  });
  const bannerGeo = new THREE.PlaneGeometry(2.1, 3.0, 1, 4);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const b = new THREE.Mesh(bannerGeo, bannerMat);
    b.position.set(Math.sin(a) * 18.75, 3.6, Math.cos(a) * 18.75);
    b.rotation.y = a;
    group.add(b);
  }

  /* ---------------- torches ---------------- */
  const torchGroup = new THREE.Group();
  group.add(torchGroup);
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x2b1b10, roughness: 1 });
  const flameMat = new THREE.MeshBasicMaterial({ color: 0xff8a2a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false });
  const glowTex = makeRadialTexture('rgba(255,150,60,.9)', 'rgba(255,60,0,0)');
  const torches = [];
  const torchPositions = [];
  for (let i = 0; i < 8; i++) {
    const p = columnPoints[i];
    const t = new THREE.Group();
    const stick = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.11, 1.1, 6), woodMat);
    stick.position.y = 0.55;
    t.add(stick);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.16, 0.32, 8), new THREE.MeshStandardMaterial({ color: 0x22201e, metalness: 0.7, roughness: 0.5 }));
    bowl.position.y = 1.15;
    t.add(bowl);
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.24, 0.9, 6), flameMat.clone());
    flame.position.y = 1.68;
    t.add(flame);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, color: 0xff7a2a, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    glow.scale.set(2.4, 2.4, 1);
    glow.position.y = 1.65;
    t.add(glow);
    t.position.copy(p);
    t.position.y = 5.0;
    torchGroup.add(t);
    torches.push({ flame, glow, seed: Math.random() * 10 });
    torchPositions.push(t.position.clone());
    if (i % 2 === 0) {
      const light = torchLights[i / 2];
      light.position.copy(t.position);
      light.position.y += 1.4;
    }
  }

  /* ---------------- bones & debris ---------------- */
  const boneMat = new THREE.MeshStandardMaterial({ color: 0xcfc1a2, roughness: 0.85 });
  const boneGeo = new THREE.CylinderGeometry(0.045, 0.045, 0.62, 5);
  const skullGeo = new THREE.SphereGeometry(0.16, 6, 5);
  for (let i = 0; i < 16; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = rand(14.5, 18.2);
    const bone = new THREE.Mesh(boneGeo, boneMat);
    bone.position.set(Math.sin(a) * r, 0.06, Math.cos(a) * r);
    bone.rotation.set(Math.PI / 2 + rand(-0.2, 0.2), rand(0, 7), 0);
    bone.castShadow = !isMobile;
    group.add(bone);
    if (Math.random() > 0.5) {
      const skull = new THREE.Mesh(skullGeo, boneMat);
      skull.position.set(bone.position.x + rand(-0.4, 0.4), 0.1, bone.position.z + rand(-0.4, 0.4));
      skull.scale.set(1, 0.9, 1.15);
      skull.castShadow = !isMobile;
      group.add(skull);
    }
  }

  /* ---------------- dust & embers ---------------- */
  const dustCount = isMobile ? 120 : 260;
  const dustGeo = new THREE.BufferGeometry();
  const dustPos = new Float32Array(dustCount * 3);
  const dustSeed = new Float32Array(dustCount);
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = rand(-18, 18);
    dustPos[i * 3 + 1] = rand(0.1, 5.5);
    dustPos[i * 3 + 2] = rand(-18, 18);
    dustSeed[i] = Math.random() * 100;
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
  const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    color: 0xc9a173, size: 0.055, transparent: true, opacity: 0.5, depthWrite: false,
    blending: THREE.AdditiveBlending, sizeAttenuation: true
  }));
  group.add(dust);

  const emberCount = 80;
  const emberGeo = new THREE.BufferGeometry();
  const emberPos = new Float32Array(emberCount * 3);
  const emberData = [];
  for (let i = 0; i < emberCount; i++) {
    const src = torchPositions[i % torchPositions.length];
    emberPos[i * 3] = src.x + rand(-0.4, 0.4);
    emberPos[i * 3 + 1] = src.y + rand(0.5, 2.2);
    emberPos[i * 3 + 2] = src.z + rand(-0.4, 0.4);
    emberData.push({ x: emberPos[i * 3], y: emberPos[i * 3 + 1], z: emberPos[i * 3 + 2], vy: rand(0.2, 0.8), seed: Math.random() * 10 });
  }
  emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
  const embers = new THREE.Points(emberGeo, new THREE.PointsMaterial({
    color: 0xff8a3a, size: 0.1, transparent: true, opacity: 0.85, depthWrite: false,
    blending: THREE.AdditiveBlending, sizeAttenuation: true
  }));
  group.add(embers);

  /* ---------------- crowd excitement ---------------- */
  let excitement = 0;
  let time = 0;

  function cheer(amount = 1) {
    excitement = Math.min(2.4, excitement + amount);
  }

  function update(dt, t) {
    time = t;
    excitement = Math.max(0, excitement - dt * 0.42);

    // crowd bob
    const ex = 1 + excitement * 0.9;
    for (let i = 0; i < crowdCount; i++) {
      const c = crowd[i];
      const bob = Math.sin(t * c.speed * ex + c.phase) * c.amp * ex;
      dummy.position.set(c.x, c.y + 0.18 + bob, c.z);
      const lean = Math.sin(t * 0.7 + c.phase) * 0.05 * ex;
      dummy.rotation.set(0, c.a, lean);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      crowdBodies.setMatrixAt(i, dummy.matrix);
      dummy.position.y = c.y + 0.62 + bob;
      dummy.updateMatrix();
      crowdHeads.setMatrixAt(i, dummy.matrix);
    }
    crowdBodies.instanceMatrix.needsUpdate = true;
    crowdHeads.instanceMatrix.needsUpdate = true;

    // torches
    for (let i = 0; i < torches.length; i++) {
      const tr = torches[i];
      const f = 0.82 + Math.sin(t * 11 + tr.seed) * 0.1 + Math.sin(t * 23 + tr.seed * 2) * 0.06;
      tr.flame.scale.set(1 + Math.sin(t * 17 + tr.seed) * 0.12, f * 1.2, 1 + Math.cos(t * 13 + tr.seed) * 0.12);
      tr.flame.material.opacity = 0.72 + Math.sin(t * 19 + tr.seed) * 0.18;
      tr.glow.material.opacity = 0.55 + Math.sin(t * 9 + tr.seed) * 0.16;
      tr.glow.scale.setScalar(2.0 + Math.sin(t * 7 + tr.seed) * 0.35);
    }
    for (let i = 0; i < torchLights.length; i++) {
      torchLights[i].intensity = 22 + Math.sin(t * 13 + i * 2.1) * 5 + Math.sin(t * 29 + i) * 3;
    }

    // dust
    const dp = dustGeo.attributes.position.array;
    for (let i = 0; i < dustCount; i++) {
      dp[i * 3 + 1] += dt * 0.12;
      dp[i * 3] += Math.sin(t * 0.35 + dustSeed[i]) * dt * 0.08;
      if (dp[i * 3 + 1] > 5.8) dp[i * 3 + 1] = 0.1;
    }
    dustGeo.attributes.position.needsUpdate = true;

    // embers
    const ep = emberGeo.attributes.position.array;
    for (let i = 0; i < emberCount; i++) {
      const d = emberData[i];
      d.y += d.vy * dt;
      ep[i * 3] = d.x + Math.sin(t * 1.3 + d.seed) * 0.35;
      ep[i * 3 + 1] = d.y;
      ep[i * 3 + 2] = d.z + Math.cos(t * 1.1 + d.seed) * 0.35;
      if (d.y > 9) {
        d.y = torchPositions[i % torchPositions.length].y + 0.8;
      }
    }
    emberGeo.attributes.position.needsUpdate = true;

    stars.rotation.y = t * 0.004;
  }

  return {
    group, update, cheer,
    key, hemi,
    get excitement() { return excitement; },
    torchLights
  };
}

import * as THREE from '../vendor/three.module.js';
import { damp, lerp, easeOut, easeIn, clamp } from './utils.js';

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();

function makeMat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.85,
    metalness: opts.metalness ?? 0.05,
    flatShading: true,
    emissive: 0x000000,
    ...opts
  });
}

function shadowTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 2, 64, 64, 62);
  g.addColorStop(0, 'rgba(0,0,0,.6)');
  g.addColorStop(0.55, 'rgba(0,0,0,.32)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
let SHADOW_TEX = null;

