/**
 * Builds a fully rigged low-poly gladiator.
 * Returns { root, parts, hitMeshes, mats, weapon, tip, shadow, ... }
 */
export function makeFighter(opts = {}) {
  const skinColor = opts.skin ?? 0xc98f6b;
  const clothColor = opts.cloth ?? 0x5a2620;
  const armorColor = opts.armor ?? 0x6f6a5f;
  const scale = opts.scale ?? 1;
  const isBrute = !!opts.brute;

  const mats = {
    skin: makeMat(skinColor, { roughness: 0.9 }),
    cloth: makeMat(clothColor, { roughness: 0.95 }),
    armor: makeMat(armorColor, { roughness: 0.55, metalness: 0.55 }),
    leather: makeMat(0x2e2016, { roughness: 1 }),
    hair: makeMat(opts.hair ?? 0x1c1210, { roughness: 1 }),
    weapon: makeMat(0x9aa2a8, { roughness: 0.32, metalness: 0.9 }),
    metal: makeMat(0x8b9096, { roughness: 0.45, metalness: 0.8 })
  };

  const root = new THREE.Group();
  root.scale.setScalar(scale);

  const hips = new THREE.Group();
  hips.position.y = 1.04;
  root.add(hips);

  const pelvis = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.3, 0.29), mats.cloth);
  pelvis.castShadow = true;
  hips.add(pelvis);

  const belt = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.09, 0.32), mats.leather);
  belt.position.y = 0.14;
  belt.castShadow = true;
  hips.add(belt);

  const beltPlate = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.12, 0.05), mats.metal);
  beltPlate.position.set(0, 0.11, -0.17);
  hips.add(beltPlate);

  function makeLeg(side) {
    const hip = new THREE.Group();
    hip.position.set(0.135 * side, -0.1, 0);
    hips.add(hip);

    const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.48, 0.21), mats.skin);
    thigh.position.y = -0.23;
    thigh.castShadow = true;
    hip.add(thigh);

    const loin = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.26, 0.24), mats.cloth);
    loin.position.y = -0.1;
    hip.add(loin);

    const knee = new THREE.Group();
    knee.position.y = -0.46;
    hip.add(knee);

    const shin = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.42, 0.19), mats.skin);
    shin.position.y = -0.21;
    shin.castShadow = true;
    knee.add(shin);

    const shinGuard = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.3, 0.06), mats.leather);
    shinGuard.position.set(0, -0.17, -0.1);
    knee.add(shinGuard);

    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.11, 0.32), mats.leather);
    foot.position.set(0, -0.44, -0.06);
    foot.castShadow = true;
    knee.add(foot);

    for (const m of [thigh, loin, shin, shinGuard, foot]) m.userData.partKey = side < 0 ? 'legL' : 'legR';
    return { node: hip, knee };
  }

  const legL = makeLeg(-1);
  const legR = makeLeg(1);

  const torso = new THREE.Group();
  torso.position.y = 0.12;
  hips.add(torso);

  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.54, 0.68, 0.32), mats.cloth);
  chest.position.y = 0.32;
  chest.castShadow = true;
  torso.add(chest);

  const abs = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.3, 0.29), mats.skin);
  abs.position.y = 0.08;
  torso.add(abs);

  const chestArmor = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.46, 0.36), mats.armor);
  chestArmor.position.y = 0.38;
  chestArmor.castShadow = true;
  torso.add(chestArmor);

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.14, 6), mats.skin);
  neck.position.y = 0.69;
  torso.add(neck);

  const head = new THREE.Group();
  head.position.y = 0.72;
  torso.add(head);

  const skull = new THREE.Mesh(new THREE.BoxGeometry(0.29, 0.34, 0.29), mats.skin);
  skull.position.y = 0.16;
  skull.castShadow = true;
  head.add(skull);

  const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.12, 0.24), mats.skin);
  jaw.position.set(0, 0.005, -0.01);
  head.add(jaw);

  const nose = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.08, 0.06), mats.skin);
  nose.position.set(0, 0.15, -0.165);
  head.add(nose);

  const eyeMat = new THREE.MeshStandardMaterial({ color: 0xf5e8d8, emissive: 0x3a2a20, roughness: 0.6, flatShading: true });
  const pupilMat = new THREE.MeshBasicMaterial({ color: 0x120808 });
  for (const s of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.BoxGeometry(0.062, 0.045, 0.03), eyeMat);
    eye.position.set(0.075 * s, 0.19, -0.155);
    head.add(eye);
    const pupil = new THREE.Mesh(new THREE.BoxGeometry(0.024, 0.03, 0.02), pupilMat);
    pupil.position.set(0.075 * s, 0.19, -0.172);
    head.add(pupil);
  }

  const hair = new THREE.Mesh(new THREE.BoxGeometry(0.31, 0.1, 0.31), mats.hair);
  hair.position.y = 0.34;
  head.add(hair);

  if (isBrute) {
    const helmet = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.2, 0.36), mats.armor);
    helmet.position.y = 0.31;
    helmet.castShadow = true;
    head.add(helmet);
    const hornGeo = new THREE.ConeGeometry(0.06, 0.26, 5);
    for (const s of [-1, 1]) {
      const horn = new THREE.Mesh(hornGeo, mats.metal);
      horn.position.set(0.2 * s, 0.34, 0);
      horn.rotation.z = -0.7 * s;
      head.add(horn);
    }
    const beard = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.16, 0.12), mats.hair);
    beard.position.set(0, -0.02, -0.17);
    head.add(beard);
  }

  const headParts = [skull, jaw, nose, hair];
  if (isBrute) headParts.push(...head.children.filter(c => !headParts.includes(c) && c !== head.children[0]));
  for (const m of head.children) {
    if (m.isMesh) m.userData.partKey = 'head';
  }

  function makeArm(side) {
    const shoulder = new THREE.Group();
    shoulder.position.set(0.34 * side, 0.58, 0);
    shoulder.rotation.z = 0.1 * side;
    torso.add(shoulder);

    const pauldron = new THREE.Mesh(new THREE.SphereGeometry(0.15, 7, 5, 0, Math.PI * 2, 0, Math.PI / 2), mats.armor);
    pauldron.position.y = 0.01;
    pauldron.scale.set(1.15, 0.8, 1.1);
    pauldron.userData.partKey = 'torso';
    shoulder.add(pauldron);

    const upper = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.4, 0.17), mats.skin);
    upper.position.y = -0.2;
    upper.castShadow = true;
    shoulder.add(upper);

    const elbow = new THREE.Group();
    elbow.position.y = -0.4;
    shoulder.add(elbow);

    const fore = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.36, 0.15), mats.skin);
    fore.position.y = -0.18;
    fore.castShadow = true;
    elbow.add(fore);

    const bracer = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.18, 0.18), mats.leather);
    bracer.position.y = -0.24;
    elbow.add(bracer);

    const hand = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.14, 0.15), mats.skin);
    hand.position.y = -0.4;
    elbow.add(hand);

    for (const m of [upper, fore, bracer, hand]) m.userData.partKey = side < 0 ? 'armL' : 'armR';
    return { node: shoulder, elbow, hand };
  }

  const armL = makeArm(-1);
  const armR = makeArm(1);

  // weapon
  const weaponType = opts.weapon ?? 'sword';
  let weapon = null;
  if (weaponType === 'sword') weapon = buildSword(mats);
  else if (weaponType === 'hammer') weapon = buildHammer(mats);
  else if (weaponType === 'axe') weapon = buildAxe(mats);
  else if (weaponType === 'club') weapon = buildClub(mats);
  if (weapon) {
    weapon.position.set(0, -0.4, 0);
    weapon.rotation.x = weaponType === 'hammer' ? -1.85 : -1.75;
    weapon.rotation.z = weaponType === 'axe' ? -0.15 : 0;
    armR.elbow.add(weapon);
    if (weaponType === 'hammer' || weaponType === 'club') weapon.scale.setScalar(0.94);
  }

  const tip = new THREE.Object3D();
  if (weapon) {
    tip.position.copy(weapon.userData.tipLocal);
    weapon.add(tip);
  }

  const hitMeshes = [];
  root.traverse(o => {
    if (o.isMesh && o.userData.partKey) hitMeshes.push(o);
  });

  head.traverse(o => { if (o.isMesh) o.userData.partKey = 'head'; });

  const parts = {
    head: { node: head, hp: 38, maxHp: 38, key: 'head' },
    torso: { node: torso, hp: 120, maxHp: 120, key: 'torso' },
    armL: { node: armL.node, hp: 34, maxHp: 34, key: 'armL' },
    armR: { node: armR.node, hp: 34, maxHp: 34, key: 'armR' },
    legL: { node: legL.node, hp: 46, maxHp: 46, key: 'legL' },
    legR: { node: legR.node, hp: 46, maxHp: 46, key: 'legR' }
  };
  if (isBrute) {
    for (const k of Object.keys(parts)) {
      parts[k].hp *= 1.9;
      parts[k].maxHp *= 1.9;
    }
  }

  if (!SHADOW_TEX) SHADOW_TEX = shadowTexture();
  const shadow = new THREE.Mesh(
    new THREE.PlaneGeometry(1.5, 1.5),
    new THREE.MeshBasicMaterial({ map: SHADOW_TEX, transparent: true, opacity: 0.75, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.02;

  return {
    root, hips, torso, head, legL, legR, armL, armR,
    parts, hitMeshes, mats, weapon, tip, shadow, scale, isBrute,
    weaponType,
    hp: isBrute ? 260 : 100,
    maxHp: isBrute ? 260 : 100,
    dead: false,
    deathT: 0,
    walkPhase: Math.random() * 7,
    attackT: -1,
    attackDur: 0.5,
    attackCombo: 0,
    staggerT: 0,
    flashT: 0,
    moving: 0,
    radius: 0.42 * scale,
    height: 2.14 * scale,
    baseHipsY: 1.04,
    lastPos: new THREE.Vector3()
  };
}

export function setHurtFlash(f, amount) {
  f.flashT = Math.max(f.flashT, amount);
}

export function animateFighter(f, dt, t, opts = {}) {
  if (f.dead) {
    f.deathT += dt;
    const k = Math.min(1, f.deathT * 3.2);
    f.root.rotation.x = damp(f.root.rotation.x, -1.42, 9, dt);
    f.hips.position.y = damp(f.hips.position.y, f.baseHipsY * 0.28, 7, dt);
    f.hips.rotation.z = damp(f.hips.rotation.z, 0.12, 3, dt);
    f.shadow.position.set(f.root.position.x, 0.022, f.root.position.z);
    return;
  }

  if (f.flashT > 0) {
    f.flashT = Math.max(0, f.flashT - dt * 3.4);
    const e = f.flashT * 0.65;
    f.mats.skin.emissive.setRGB(e, e * 0.09, e * 0.05);
    f.mats.cloth.emissive.setRGB(e, e * 0.09, e * 0.05);
    f.mats.armor.emissive.setRGB(e * 0.6, e * 0.05, e * 0.03);
  } else {
    f.mats.skin.emissive.setRGB(0, 0, 0);
    f.mats.cloth.emissive.setRGB(0, 0, 0);
    f.mats.armor.emissive.setRGB(0, 0, 0);
  }

  const moving = f.moving;
  f.walkPhase += dt * (2.2 + moving * 1.45);
  const stride = Math.min(1, moving / 4.2);
  const swing = Math.sin(f.walkPhase);
  const swing2 = Math.sin(f.walkPhase + Math.PI);

  let bob = Math.abs(Math.sin(f.walkPhase)) * 0.045 * stride;
  f.hips.position.y = f.baseHipsY + bob;
  f.hips.rotation.z = Math.sin(f.walkPhase) * 0.025 * stride;
  f.hips.rotation.y = Math.sin(f.walkPhase) * 0.06 * stride;

  f.legL.node.rotation.x = swing * 0.72 * stride;
  f.legR.node.rotation.x = swing2 * 0.72 * stride;
  f.legL.knee.rotation.x = Math.max(0, -swing) * 0.65 * stride;
  f.legR.knee.rotation.x = Math.max(0, -swing2) * 0.65 * stride;

  // arms rest
  let armLX = swing2 * 0.45 * stride;
  let armRX = swing * 0.3 * stride;
  let armLZ = -0.1, armRZ = 0.1;
  let torsoY = 0;
  let torsoX = 0;
  let lean = 0;

  if (f.attackT >= 0) {
    const p = clamp(f.attackT / f.attackDur, 0, 1);
    const heavy = f.weaponType === 'hammer' || f.weaponType === 'club';
    if (heavy) {
      if (p < 0.38) {
        const q = easeOut(p / 0.38);
        armRX = lerp(armRX, -2.75, q);
        armLX = lerp(armLX, -2.45, q);
        torsoX = lerp(0, 0.2, q);
        f.hips.position.y += q * 0.07;
      } else if (p < 0.58) {
        const q = easeIn((p - 0.38) / 0.2);
        armRX = lerp(-2.75, 0.85, q);
        armLX = lerp(-2.45, 0.55, q);
        torsoX = lerp(0.2, -0.35, q);
        f.hips.position.y -= q * 0.12;
        f.hips.rotation.x = -0.12 * q;
      } else {
        const q = easeOut((p - 0.58) / 0.42);
        armRX = lerp(0.85, swing * 0.3 * stride, q);
        armLX = lerp(0.55, swing2 * 0.45 * stride, q);
        torsoX = lerp(-0.35, 0, q);
        f.hips.rotation.x = lerp(-0.12, 0, q);
      }
    } else {
      if (p < 0.26) {
        const q = easeOut(p / 0.26);
        armRX = lerp(armRX, -2.35, q);
        armRZ = lerp(0.1, 0.75, q);
        torsoY = lerp(0, 0.55, q);
      } else if (p < 0.52) {
        const q = easeIn((p - 0.26) / 0.26);
        armRX = lerp(-2.35, 0.75, q);
        armRZ = lerp(0.75, -0.55, q);
        torsoY = lerp(0.55, -0.5, q);
      } else {
        const q = easeOut((p - 0.52) / 0.48);
        armRX = lerp(0.75, swing * 0.3 * stride, q);
        armRZ = lerp(-0.55, 0.1, q);
        torsoY = lerp(-0.5, 0, q);
      }
    }
  }

  if (f.staggerT > 0) {
    f.staggerT -= dt;
    lean = Math.sin(f.staggerT * 22) * 0.16;
  }

  f.armL.node.rotation.x = damp(f.armL.node.rotation.x, armLX, 18, dt);
  f.armR.node.rotation.x = damp(f.armR.node.rotation.x, armRX, 22, dt);
  f.armL.node.rotation.z = damp(f.armL.node.rotation.z, armLZ, 12, dt);
  f.armR.node.rotation.z = damp(f.armR.node.rotation.z, armRZ, 18, dt);
  f.torso.rotation.y = damp(f.torso.rotation.y, torsoY, 16, dt);
  f.torso.rotation.x = damp(f.torso.rotation.x, torsoX + lean, 14, dt);

  f.shadow.position.set(f.root.position.x, 0.022, f.root.position.z);
  f.shadow.material.opacity = 0.72;

  if (f.attackT >= 0) {
    f.attackT += dt;
    if (f.attackT > f.attackDur + 0.14) f.attackT = -1;
  }
  if (f.staggerT < -1) f.staggerT = 0;
}

export function disposeFighter(f, scene) {
  if (f.root.parent) f.root.parent.remove(f.root);
  if (f.shadow.parent) f.shadow.parent.remove(f.shadow);
  f.shadow.geometry.dispose();
  f.shadow.material.dispose();
}

export function getWeaponTipWorld(f, out = _v) {
  if (!f.tip) return out.set(f.root.position.x, 1.4, f.root.position.z);
  f.tip.getWorldPosition(out);
  return out;
}

import * as THREE from '../vendor/three.module.js';
import { rand, randInt, clamp, makeBloodBlobTexture } from './utils.js';

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _e = new THREE.Euler();
const _s = new THREE.Vector3();
const _p = new THREE.Vector3();
const _off = new THREE.Vector3();

export class Gore {
  constructor(scene, isMobile = false) {
    this.scene = scene;
    this.isMobile = isMobile;
    this.time = 0;

    /* ---------- droplets ---------- */
    this.maxDrops = isMobile ? 520 : 1100;
    this.dropPos = new Float32Array(this.maxDrops * 3);
    this.dropCol = new Float32Array(this.maxDrops * 3);
    this.dropVel = new Float32Array(this.maxDrops * 3);
    this.dropLife = new Float32Array(this.maxDrops);
    this.dropMax = new Float32Array(this.maxDrops);
    this.dropSize = new Float32Array(this.maxDrops);
    this.dropHead = 0;
    for (let i = 0; i < this.maxDrops; i++) {
      this.dropPos[i * 3 + 1] = -100;
      this.dropLife[i] = 0;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.dropPos, 3));
    g.setAttribute('color', new THREE.BufferAttribute(this.dropCol, 3));
    g.setAttribute('size', new THREE.BufferAttribute(this.dropSize, 1));
    this.dropGeo = g;
    this.dropMat = new THREE.PointsMaterial({
      color: 0xffffff, vertexColors: true, size: 0.09, sizeAttenuation: true,
      transparent: true, opacity: 0.95, depthWrite: false
    });
    this.drops = new THREE.Points(g, this.dropMat);
    this.drops.frustumCulled = false;
    this.drops.renderOrder = 3;
    scene.add(this.drops);

    /* ---------- mist ---------- */
    this.maxMist = isMobile ? 70 : 130;
    this.mistPos = new Float32Array(this.maxMist * 3);
    this.mistVel = new Float32Array(this.maxMist * 3);
    this.mistLife = new Float32Array(this.maxMist);
    this.mistHead = 0;
    for (let i = 0; i < this.maxMist; i++) this.mistPos[i * 3 + 1] = -100;
    const mg = new THREE.BufferGeometry();
    mg.setAttribute('position', new THREE.BufferAttribute(this.mistPos, 3));
    this.mistGeo = mg;
    this.mist = new THREE.Points(mg, new THREE.PointsMaterial({
      color: 0x560005, size: 0.5, sizeAttenuation: true, transparent: true,
      opacity: 0.24, depthWrite: false
    }));
    this.mist.frustumCulled = false;
    scene.add(this.mist);

    /* ---------- decals ---------- */
    this.maxDecals = isMobile ? 200 : 460;
    const blob = makeBloodBlobTexture();
    blob.anisotropy = 8;
    this.decalMat = new THREE.MeshBasicMaterial({
      map: blob, transparent: true, depthWrite: false, opacity: 0.92,
      polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3
    });
    this.decals = new THREE.InstancedMesh(new THREE.PlaneGeometry(1, 1), this.decalMat, this.maxDecals);
    this.decals.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.decals.frustumCulled = false;
    this.decals.renderOrder = 2;
    this.decalHead = 0;
    this.pools = new Map();
    const hide = new THREE.Matrix4().makeTranslation(0, -100, 0);
    for (let i = 0; i < this.maxDecals; i++) {
      this.decals.setMatrixAt(i, hide);
      this.decals.setColorAt(i, new THREE.Color(0x5a0104));
    }
    this.decals.instanceColor.needsUpdate = true;
    scene.add(this.decals);

    /* ---------- meat chunks ---------- */
    this.maxChunks = isMobile ? 50 : 90;
    this.chunks = new THREE.InstancedMesh(
      new THREE.IcosahedronGeometry(0.085, 0),
      new THREE.MeshStandardMaterial({ color: 0x6b0204, roughness: 0.75, flatShading: true }),
      this.maxChunks
    );
    this.chunks.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.chunks.frustumCulled = false;
    this.chunks.castShadow = false;
    this.chunkData = [];
    this.chunkHead = 0;
    for (let i = 0; i < this.maxChunks; i++) {
      this.chunks.setMatrixAt(i, hide);
      this.chunkData.push({ active: false, pos: new THREE.Vector3(0, -100, 0), vel: new THREE.Vector3(), rot: new THREE.Euler(), ang: new THREE.Vector3(), life: 0 });
    }
    scene.add(this.chunks);

    /* ---------- blood fountains ---------- */
    this.fountains = [];
  }

  spawnBlood(pos, dir, count = 18, power = 1) {
    const n = this.isMobile ? Math.ceil(count * 0.6) : count;
    for (let k = 0; k < n; k++) {
      const i = this.dropHead;
      this.dropHead = (this.dropHead + 1) % this.maxDrops;
      const i3 = i * 3;
      this.dropPos[i3] = pos.x + rand(-0.12, 0.12);
      this.dropPos[i3 + 1] = pos.y + rand(-0.12, 0.12);
      this.dropPos[i3 + 2] = pos.z + rand(-0.12, 0.12);
      const sp = rand(1.2, 4.4) * power;
      const dx = dir ? dir.x : rand(-1, 1);
      const dy = dir ? dir.y : rand(0, 1);
      const dz = dir ? dir.z : rand(-1, 1);
      this.dropVel[i3] = dx * sp + rand(-1.7, 1.7);
      this.dropVel[i3 + 1] = Math.abs(dy) * sp * 0.6 + rand(0.6, 3.6) * power;
      this.dropVel[i3 + 2] = dz * sp + rand(-1.7, 1.7);
      const dark = rand(0.25, 0.85);
      this.dropCol[i3] = 0.34 + dark * 0.3;
      this.dropCol[i3 + 1] = 0.004 + dark * 0.02;
      this.dropCol[i3 + 2] = 0.008 + dark * 0.03;
      this.dropLife[i] = rand(0.45, 1.15) * power;
      this.dropMax[i] = this.dropLife[i];
      this.dropSize[i] = rand(0.5, 1.4);
    }
    this.dropGeo.attributes.position.needsUpdate = true;
    this.dropGeo.attributes.color.needsUpdate = true;

    // little mist puff
    for (let k = 0; k < Math.ceil(n / 6); k++) {
      const i = this.mistHead;
      this.mistHead = (this.mistHead + 1) % this.maxMist;
      const i3 = i * 3;
      this.mistPos[i3] = pos.x + rand(-0.2, 0.2);
      this.mistPos[i3 + 1] = pos.y + rand(-0.1, 0.3);
      this.mistPos[i3 + 2] = pos.z + rand(-0.2, 0.2);
      this.mistVel[i3] = rand(-0.7, 0.7);
      this.mistVel[i3 + 1] = rand(0.2, 1.1);
      this.mistVel[i3 + 2] = rand(-0.7, 0.7);
      this.mistLife[i] = rand(0.5, 1.1);
    }
    this.mistGeo.attributes.position.needsUpdate = true;
  }

  spawnPool(pos, size = 1.2, color = 0x4a0103) {
    const i = this.decalHead;
    this.decalHead = (this.decalHead + 1) % this.maxDecals;
    const existing = this.pools.get(i);
    if (existing) this.pools.delete(i);
    this.pools.set(i, {
      i,
      x: pos.x + rand(-0.15, 0.15),
      z: pos.z + rand(-0.15, 0.15),
      cur: size * 0.35,
      target: size * rand(0.85, 1.35),
      rot: rand(0, Math.PI * 2),
      color: new THREE.Color(color).offsetHSL(0, 0, rand(-0.03, 0.03)),
      low: true
    });
    const m = this.decals;
    _e.set(-Math.PI / 2, 0, rand(0, Math.PI * 2));
    _q.setFromEuler(_e);
    _p.set(pos.x, 0.018 + rand(0, 0.002), pos.z);
    _s.set(size * 0.4, size * 0.4, 1);
    _m.compose(_p, _q, _s);
    m.setMatrixAt(i, _m);
    m.setColorAt(i, this.pools.get(i).color);
    m.instanceMatrix.needsUpdate = true;
    if (m.instanceColor) m.instanceColor.needsUpdate = true;
  }

  spawnDecal(pos, size = 0.5) {
    const i = this.decalHead;
    this.decalHead = (this.decalHead + 1) % this.maxDecals;
    const m = this.decals;
    _e.set(-Math.PI / 2, 0, rand(0, Math.PI * 2));
    _q.setFromEuler(_e);
    _p.set(pos.x, 0.017 + rand(0, 0.003), pos.z);
    _s.set(size, size * rand(0.7, 1.2), 1);
    _m.compose(_p, _q, _s);
    m.setMatrixAt(i, _m);
    m.setColorAt(i, new THREE.Color(0x5a0104).offsetHSL(0, 0, rand(-0.04, 0.02)));
    m.instanceMatrix.needsUpdate = true;
    if (m.instanceColor) m.instanceColor.needsUpdate = true;
  }

  spawnChunks(pos, dir, count = 5, power = 1) {
    for (let k = 0; k < count; k++) {
      const i = this.chunkHead;
      this.chunkHead = (this.chunkHead + 1) % this.maxChunks;
      const c = this.chunkData[i];
      c.active = true;
      c.pos.set(pos.x + rand(-0.1, 0.1), pos.y + rand(-0.1, 0.18), pos.z + rand(-0.1, 0.1));
      c.vel.set(
        (dir?.x ?? 0) * rand(1, 4) * power + rand(-2.8, 2.8),
        rand(1.5, 4.6) * power,
        (dir?.z ?? 0) * rand(1, 4) * power + rand(-2.8, 2.8)
      );
      c.rot.set(rand(0, 6), rand(0, 6), rand(0, 6));
      c.ang.set(rand(-9, 9), rand(-9, 9), rand(-9, 9));
      c.life = rand(5, 11);
      c.scale = rand(0.6, 1.7);
      c.stain = false;
    }
  }

  addFountain(obj, offset, duration = 1.2, power = 1.2, chunks = false) {
    this.fountains.push({ obj, offset: offset.clone(), t: duration, duration, power, chunks, acc: 0 });
  }

  update(dt) {
    this.time += dt;
    const pos = this.dropPos, vel = this.dropVel;

    for (let i = 0; i < this.maxDrops; i++) {
      if (this.dropLife[i] <= 0) continue;
      const i3 = i * 3;
      this.dropLife[i] -= dt;
      vel[i3 + 1] -= 17 * dt;
      pos[i3] += vel[i3] * dt;
      pos[i3 + 1] += vel[i3 + 1] * dt;
      pos[i3 + 2] += vel[i3 + 2] * dt;
      if (pos[i3 + 1] <= 0.02) {
        pos[i3 + 1] = 0.02;
        if (Math.random() < 0.16) this.spawnDecal({ x: pos[i3], z: pos[i3 + 2] }, rand(0.18, 0.6));
        if (this.dropLife[i] > 0.12) {
          this.dropLife[i] = 0.12;
          vel[i3] *= 0.2; vel[i3 + 1] *= -0.12; vel[i3 + 2] *= 0.2;
        }
      }
      if (this.dropLife[i] <= 0) {
        pos[i3 + 1] = -100;
        this.dropLife[i] = 0;
      }
    }
    this.dropGeo.attributes.position.needsUpdate = true;

    const mp = this.mistPos, mv = this.mistVel;
    for (let i = 0; i < this.maxMist; i++) {
      if (this.mistLife[i] <= 0) continue;
      const i3 = i * 3;
      this.mistLife[i] -= dt;
      mp[i3] += mv[i3] * dt;
      mp[i3 + 1] += mv[i3 + 1] * dt;
      mp[i3 + 2] += mv[i3 + 2] * dt;
      mv[i3] *= 0.97;
      mv[i3 + 1] *= 0.97;
      mv[i3 + 2] *= 0.97;
      if (this.mistLife[i] <= 0) { mp[i3 + 1] = -100; this.mistLife[i] = 0; }
    }
    this.mistGeo.attributes.position.needsUpdate = true;

    // grow fresh pools
    if (this.pools.size) {
      let changed = false;
      for (const pool of this.pools.values()) {
        const next = Math.min(pool.target, pool.cur + dt * pool.target * 1.9);
        if (next !== pool.cur) {
          pool.cur = next;
          _e.set(-Math.PI / 2, 0, pool.rot);
          _q.setFromEuler(_e);
          _p.set(pool.x, 0.018, pool.z);
          _s.set(pool.cur, pool.cur, 1);
          _m.compose(_p, _q, _s);
          this.decals.setMatrixAt(pool.i, _m);
          changed = true;
        }
      }
      if (changed) this.decals.instanceMatrix.needsUpdate = true;
    }

    // meat chunks
    let chunkChanged = false;
    for (let i = 0; i < this.maxChunks; i++) {
      const c = this.chunkData[i];
      if (!c.active) continue;
      c.life -= dt;
      c.vel.y -= 19 * dt;
      c.pos.addScaledVector(c.vel, dt);
      c.rot.x += c.ang.x * dt;
      c.rot.y += c.ang.y * dt;
      c.rot.z += c.ang.z * dt;
      if (c.pos.y < 0.06) {
        c.pos.y = 0.06;
        if (c.vel.y < -2 && Math.random() < 0.5) {
          c.vel.y *= -0.32;
          c.vel.x *= 0.55;
          c.vel.z *= 0.55;
          c.ang.multiplyScalar(0.55);
        } else {
          if (!c.stain) {
            c.stain = true;
            this.spawnDecal({ x: c.pos.x, z: c.pos.z }, rand(0.3, 0.7));
          }
          c.vel.set(0, 0, 0);
          c.ang.set(0, 0, 0);
        }
      }
      if (c.life <= 0) {
        c.active = false;
        _m.makeTranslation(0, -100, 0);
      } else {
        _q.setFromEuler(c.rot);
        _s.setScalar(c.scale * Math.min(1, c.life));
        _m.compose(c.pos, _q, _s);
      }
      this.chunks.setMatrixAt(i, _m);
      chunkChanged = true;
    }
    if (chunkChanged) this.chunks.instanceMatrix.needsUpdate = true;

    // blood fountains
    for (let i = this.fountains.length - 1; i >= 0; i--) {
      const f = this.fountains[i];
      f.t -= dt;
      f.acc += dt;
      const rate = 0.03;
      while (f.acc > rate) {
        f.acc -= rate;
        if (f.obj && f.obj.parent) {
          _off.copy(f.offset);
          f.obj.localToWorld(_off);
        } else {
          _off.copy(f.offset);
        }
        this.spawnBlood(_off, { x: rand(-0.4, 0.4), y: 1, z: rand(-0.4, 0.4) }, 2, f.power);
        if (f.chunks && Math.random() < 0.12) this.spawnChunks(_off, { x: 0, z: 0 }, 1, f.power * 0.8);
      }
      if (f.t <= 0) this.fountains.splice(i, 1);
    }
  }

  clear() {
    const hide = new THREE.Matrix4().makeTranslation(0, -100, 0);
    this.dropLife.fill(0);
    for (let i = 0; i < this.maxDrops; i++) this.dropPos[i * 3 + 1] = -100;
    this.dropGeo.attributes.position.needsUpdate = true;
    this.mistLife.fill(0);
    for (let i = 0; i < this.maxMist; i++) this.mistPos[i * 3 + 1] = -100;
    this.mistGeo.attributes.position.needsUpdate = true;
    for (let i = 0; i < this.maxDecals; i++) {
      this.decals.setMatrixAt(i, hide);
      this.decals.setColorAt(i, new THREE.Color(0x5a0104));
    }
    this.decals.instanceMatrix.needsUpdate = true;
    if (this.decals.instanceColor) this.decals.instanceColor.needsUpdate = true;
    this.pools.clear();
    for (let i = 0; i < this.maxChunks; i++) {
      this.chunkData[i].active = false;
      this.chunks.setMatrixAt(i, hide);
    }
    this.chunks.instanceMatrix.needsUpdate = true;
    this.fountains.length = 0;
    this.dropHead = 0;
    this.decalHead = 0;
    this.chunkHead = 0;
  }
}

import { rand } from './utils.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuf = null;
    this.ambientGain = null;
    this.crowdGain = null;
    this.started = false;
    this.muted = false;
    this.lowHealth = false;
    this.heartT = 0;
    this.volume = 0.55;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 2);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;

    this.startAmbient();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : this.volume;
  }

  now() { return this.ctx.currentTime; }

  noise({ dur = 0.3, freq = 800, q = 1.2, gain = 0.3, type = 'bandpass', sweep = null, delay = 0, attack = 0.005 }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.playbackRate.value = rand(0.9, 1.1);
    const filt = this.ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(freq, t);
    filt.Q.value = q;
    if (sweep) filt.frequency.exponentialRampToValueAtTime(Math.max(20, sweep), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filt).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  tone({ freq = 200, endFreq = null, dur = 0.3, gain = 0.2, type = 'sine', delay = 0, attack = 0.005 }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(10, endFreq), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  startAmbient() {
    if (this.started || !this.ctx) return;
    this.started = true;
    const t = this.now();

    // low drone
    const drone = this.ctx.createOscillator();
    drone.type = 'sine';
    drone.frequency.value = 42;
    const dg = this.ctx.createGain();
    dg.gain.value = 0.055;
    drone.connect(dg).connect(this.master);
    drone.start();

    const drone2 = this.ctx.createOscillator();
    drone2.type = 'triangle';
    drone2.frequency.value = 63.5;
    const dg2 = this.ctx.createGain();
    dg2.gain.value = 0.02;
    drone2.connect(dg2).connect(this.master);
    drone2.start();

    // crowd murmur
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    const filt = this.ctx.createBiquadFilter();
    filt.type = 'bandpass';
    filt.frequency.value = 620;
    filt.Q.value = 0.6;
    const g = this.ctx.createGain();
    g.gain.value = 0.028;
    src.connect(filt).connect(g).connect(this.master);
    src.start(t);
    this.crowdGain = g;

    // slow swell LFO
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.09;
    const lg = this.ctx.createGain();
    lg.gain.value = 0.012;
    lfo.connect(lg).connect(g.gain);
    lfo.start(t);
  }

  swing(heavy = false) {
    if (!this.ctx) return;
    if (heavy) {
      this.noise({ dur: 0.34, freq: 320, sweep: 90, q: 0.8, gain: 0.26, type: 'bandpass' });
      this.tone({ freq: 90, endFreq: 40, dur: 0.28, gain: 0.14, type: 'sine' });
    } else {
      this.noise({ dur: 0.22, freq: 1600, sweep: 380, q: 1.1, gain: 0.2, type: 'bandpass' });
    }
  }

  hitFlesh(power = 1) {
    if (!this.ctx) return;
    this.noise({ dur: 0.16, freq: 240, sweep: 100, q: 0.7, gain: 0.24 * power, type: 'lowpass' });
    this.tone({ freq: 120, endFreq: 45, dur: 0.22, gain: 0.25 * power, type: 'sine' });
    this.noise({ dur: 0.08, freq: 3200, q: 0.7, gain: 0.1 * power, type: 'highpass', delay: 0.01 });
  }

  hitMetal() {
    if (!this.ctx) return;
    this.tone({ freq: 1850, endFreq: 1400, dur: 0.2, gain: 0.08, type: 'square' });
    this.tone({ freq: 2700, endFreq: 2100, dur: 0.14, gain: 0.05, type: 'triangle' });
    this.noise({ dur: 0.06, freq: 5000, q: 1, gain: 0.14, type: 'highpass' });
  }

  crush() {
    if (!this.ctx) return;
    this.tone({ freq: 70, endFreq: 24, dur: 0.5, gain: 0.5, type: 'sine' });
    this.noise({ dur: 0.42, freq: 380, sweep: 70, q: 0.5, gain: 0.4, type: 'lowpass' });
    // bone cracks
    for (let i = 0; i < 4; i++) {
      this.noise({ dur: 0.035, freq: rand(1400, 3200), q: 2, gain: 0.2, type: 'bandpass', delay: 0.02 + i * 0.035 });
    }
  }

  boneSnap() {
    for (let i = 0; i < 3; i++) {
      this.noise({ dur: 0.04, freq: rand(900, 2400), q: 3, gain: 0.18, type: 'bandpass', delay: i * 0.03 });
    }
  }

  sever() {
    if (!this.ctx) return;
    this.hitFlesh(1.1);
    this.boneSnap();
    this.noise({ dur: 0.5, freq: 700, sweep: 120, q: 0.6, gain: 0.16, type: 'lowpass', delay: 0.05 });
  }

  scream(pitch = 1) {
    if (!this.ctx || this.muted) return;
    const t = this.now();
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    const f0 = rand(210, 360) * pitch;
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(f0 * 0.38, t + 0.55);
    const vib = this.ctx.createOscillator();
    vib.frequency.value = rand(9, 15);
    const vg = this.ctx.createGain();
    vg.gain.value = 18;
    vib.connect(vg).connect(osc.frequency);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.09, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.6);
    const filt = this.ctx.createBiquadFilter();
    filt.type = 'bandpass';
    filt.frequency.value = 900;
    filt.Q.value = 1.2;
    osc.connect(filt).connect(g).connect(this.master);
    osc.start(t); vib.start(t);
    osc.stop(t + 0.7); vib.stop(t + 0.7);
  }

  hurt() {
    if (!this.ctx) return;
    this.tone({ freq: 95, endFreq: 38, dur: 0.3, gain: 0.3, type: 'sine' });
    this.noise({ dur: 0.2, freq: 900, sweep: 200, q: 0.8, gain: 0.18, type: 'lowpass' });
  }

  playerDeath() {
    if (!this.ctx) return;
    this.tone({ freq: 55, endFreq: 18, dur: 1.6, gain: 0.4, type: 'sine' });
    this.noise({ dur: 1.4, freq: 500, sweep: 60, q: 0.4, gain: 0.22, type: 'lowpass' });
    this.scream(0.7);
  }

  cheer(strength = 1) {
    if (!this.ctx || this.muted) return;
    if (this.crowdGain) {
      const t = this.now();
      this.crowdGain.gain.cancelScheduledValues(t);
      this.crowdGain.gain.setValueAtTime(this.crowdGain.gain.value, t);
      this.crowdGain.gain.linearRampToValueAtTime(0.05 + 0.06 * strength, t + 0.25);
      this.crowdGain.gain.linearRampToValueAtTime(0.03, t + 2.4);
    }
    this.noise({ dur: 1.4, freq: 700, q: 0.5, gain: 0.09 * strength, type: 'bandpass', attack: 0.3 });
    this.noise({ dur: 1.0, freq: 1500, q: 0.7, gain: 0.05 * strength, type: 'bandpass', delay: 0.12, attack: 0.2 });
  }

  gong() {
    if (!this.ctx) return;
    this.tone({ freq: 150, endFreq: 96, dur: 1.7, gain: 0.28, type: 'sine', attack: 0.01 });
    this.tone({ freq: 320, endFreq: 210, dur: 1.3, gain: 0.12, type: 'triangle', attack: 0.01 });
    this.noise({ dur: 1.2, freq: 400, q: 0.4, gain: 0.1, type: 'lowpass' });
  }

  setLowHealth(on) {
    if (on === this.lowHealth) return;
    this.lowHealth = on;
    this.heartT = 0;
  }

  update(dt) {
    if (!this.ctx || this.muted) return;
    if (this.lowHealth) {
      this.heartT -= dt;
      if (this.heartT <= 0) {
        this.heartT = 0.82;
        this.tone({ freq: 52, endFreq: 34, dur: 0.16, gain: 0.16, type: 'sine' });
        this.tone({ freq: 46, endFreq: 30, dur: 0.14, gain: 0.1, type: 'sine', delay: 0.19 });
      }
    }
  }
}

